class TestFitnessTracker(unittest.TestCase):
    def test_condition_judge_normal(self):
        fitnessTracker = FitnessTracker(1.8, 70, 20, "male")
        self.assertEqual(fitnessTracker.condition_judge(), 0)

    def test_condition_judge_too_fat(self):
        fitnessTracker = FitnessTracker(1.8, 100, 20, "male")
        self.assertEqual(fitnessTracker.condition_judge(), -1)

